# search offsets and value predicates predicting output3 as conjunction of left==a and right-shifted==b
best=[]
for dy in range(-2,3):
 for dx in range(-3,4):
  for a in (5,7):
   for b in (5,6):
    tp=fp=fn=0
    for r in range(13):
     for c in range(11):
      rr,cc=r+dy,c+dx
      if 0<=rr<13 and 0<=cc<11:
       pred=(g2[r][c]==a and g2[rr][cc+12]==b)
      else: pred=False
      truth=o2[r][c]==3
      tp+=pred and truth; fp+=pred and not truth; fn+=not pred and truth
    best.append((tp-fp-fn,tp,fp,fn,dy,dx,a,b))
sorted(best,reverse=True)[:15]
